#!/bin/bash
# make_results.sh -- assembles RESULTS.md from RESULTS_head.md (hand-written text) and tables generated by analyze.gp / posthoc.gp. Creates no numbers.
D=${D:-research/twist_ecdlp_followup_20261107/L3-genus2-measured-arm}
cd "$D" || exit 1
{
  cat RESULTS_head.md
  echo
  echo "## GAE-band table: ratio to the matched rho R_E (geometric mean over paired instances, 95% CI), kappa_J = 1, native work priced at w = 0 / 0.1 / 1 GAE per operation"
  echo
  echo "| k | pair | w=0 | w=0.1 | w=1 | ranking across the band | gm w=0 excl. censored |"
  echo "|---|---|---|---|---|---|---|"
  grep -E '^\| [0-9]+ \| (IC-G|IC-S|IC-D|R_J)/R_E \|' out/summary.txt
  echo
  echo "## Distance remaining (geometric-mean ratio to R_E; the gap, not a pass/fail)"
  echo
  sed -n '/^## Table 6/,/^## Table 7/p' out/summary.txt | sed '1d;$d'
  echo "## Absolute costs per verified solve (geometric mean over instances; Eop for R_E, Jop for the Jacobian arms; cost at w = 0, 0.1, 1)"
  echo
  sed -n '/^## Table 1/,/^## Table 2/p' out/summary.txt | sed '1d;$d'
  echo "## Exploratory post-freeze diagnostics (posthoc.gp; not preregistered)"
  echo
  sed 1,2d out/posthoc.txt
  echo "## All preregistered tables (verbatim from out/summary.txt)"
  echo
  sed 1,3d out/summary.txt
} > RESULTS.md
